import { test, expect } from '@playwright/test';

test.describe('Table Row Highlighting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should highlight selected rows in a different colour', async ({ page }) => {
    // Verify initial table state
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify no rows are highlighted initially
    const rowCount = page.locator('[data-testid="table-row"]').count();
    expect(rowCount).toBeGreaterThan(0);

    // Verify all rows have the default background colour
    const rowBackgrounds = page.locator('[data-testid="table-row"]').filter({
      hasClass: 'table-row-highlight'
    });
    await expect(rowBackgrounds).toHaveCount(0);

    // Select the first row using getByRole
    const firstRow = page.getByRole('rowheader', { name: /row 1/i });
    await firstRow.click();

    // Verify first row is highlighted
    await expect(firstRow).toHaveClass('table-row-highlight');

    // Verify background colour has changed
    const firstRowBackground = page.locator('[data-testid="table-row-1"]').first().evaluate((el) => window.getComputedStyle(el).backgroundColor);
    expect(firstRowBackground).toBe('rgb(255, 255, 0)');

    // Verify other rows are not highlighted
    const otherRows = page.locator('[data-testid="table-row"]').filter({
      not: page.locator('[data-testid="table-row-1"]')
    });
    await expect(otherRows).toHaveCount(rowCount - 1);

    // Verify row text is still visible
    const firstRowText = page.getByText(/row 1/i);
    await expect(firstRowText).toBeVisible();

    // Verify row header is still visible
    const firstRowHeader = page.getByRole('rowheader', { name: /row 1/i });
    await expect(firstRowHeader).toBeVisible();

    // Verify row data is still visible
    const firstRowData = page.getByText(/data 1/i);
    await expect(firstRowData).toBeVisible();

    // Verify row is still selectable
    await expect(firstRow).toBeVisible();

    // Verify row is still clickable
    await expect(firstRow).toBeClickable();

    // Verify row is still scrollable
    await expect(page).toBeVisible();

    // Verify row is still accessible with keyboard navigation
    await expect(firstRow).toBeAccessible();

    // Verify row is still responsive to screen size changes
    await expect(page).toBeResponsive();

    // Verify row is still visible when scrolling
    await page.evaluate(() => {
      const table = document.querySelector('[data-testid="table-container"]');
      table.scrollTop = table.scrollHeight;
    });

    // Verify row is still visible after scrolling
    await expect(firstRow).toBeVisible();

    // Verify row is still highlighted after scrolling
    await expect(firstRow).toHaveClass('table-row-highlight');

    // Verify row highlight persists after navigation
    await page.goto('/table-list');
    await expect(firstRow).toHaveClass('table-row-highlight');

    // Verify row highlight is removed when deselected
    const secondRow = page.getByRole('rowheader', { name: /row 2/i });
    await secondRow.click();

    await expect(firstRow).not.toHaveClass('table-row-highlight');
    await expect(secondRow).toHaveClass('table-row-highlight');

    // Verify deselected row is no longer highlighted
    await expect(firstRow).not.toHaveClass('table-row-highlight');

    // Verify deselected row is still visible
    await expect(firstRow).toBeVisible();

    // Verify deselected row is still selectable
    await expect(firstRow).toBeClickable();

    // Verify deselected row is still scrollable
    await expect(page).toBeVisible();

    // Verify deselected row is still accessible with keyboard navigation
    await expect(firstRow).toBeAccessible();

    // Verify deselected row is still responsive to screen size changes
    await expect(page).toBeResponsive();

    // Verify deselected row is still visible after scrolling
    await page.evaluate(() => {
      const table = document.querySelector('[data-testid="table-container"]');
      table.scrollTop = table.scrollHeight;
    });

    await expect(firstRow).toBeVisible();

    // Verify deselected row is still highlighted after scrolling
    await expect(firstRow).not.toHaveClass('table-row-highlight');
  });

  test('should not highlight rows when table is empty', async ({ page }) => {
    // Verify table is empty
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify no rows are present
    const rowCount = page.locator('[data-testid="table-row"]').count();
    expect(rowCount).toBe(0);

    // Verify no rows are highlighted
    const rowBackgrounds = page.locator('[data-testid="table-row"]').filter({
      hasClass: 'table-row-highlight'
    });
    await expect(rowBackgrounds).toHaveCount(0);

    // Verify table header is still visible
    const tableHeader = page.getByRole('tableheader');
    await expect(tableHeader).toBeVisible();

    // Verify table footer is still visible
    const tableFooter = page.getByRole('tablefooter');
    await expect(tableFooter).toBeVisible();

    // Verify table is still scrollable
    await expect(page).toBeVisible();

    // Verify table is still responsive to screen size changes
    await expect(page).toBeResponsive();

    // Verify table is still accessible with keyboard navigation
    await expect(page).toBeAccessible();

    // Verify table is still visible after scrolling
    await page.evaluate(() => {
      const table = document.querySelector('[data-testid="table-container"]');
      table.scrollTop = table.scrollHeight;
    });

    await expect(table).toBeVisible();

    // Verify table header and footer are still visible after scrolling
    await expect(tableHeader).toBeVisible();
    await expect(tableFooter).toBeVisible();

    // Verify table is still responsive to screen size changes
    await expect(page).toBeResponsive();

    // Verify table is still accessible with keyboard navigation
    await expect(page).toBeAccessible();
  });
});
